36	pub(crate) enum HtmlSyntaxFeatures {
37	    /// Exclusive to those documents that support Astro
38	    Astro,
39	    /// Exclusive to those documents that support text expressions with {{ }}
40	    DoubleTextExpressions,
41	    /// Exclusive to those documents that support text expressions with { }
42	    SingleTextExpressions,
43	    /// Exclusive to Svelte files (for Svelte-specific directives)
44	    Svelte,
45	    /// Exclusive to those documents that support Vue
46	    Vue,
47	}
