49	impl SyntaxFeature for HtmlSyntaxFeatures {
50	    type Parser<'source> = HtmlParser<'source>;
51	
52	    fn is_supported(&self, p: &HtmlParser) -> bool {
53	        match self {
54	            Astro => p.options().frontmatter,
55	            DoubleTextExpressions => {
56	                p.options().text_expression == Some(TextExpressionKind::Double)
57	            }
58	            SingleTextExpressions => {
59	                p.options().text_expression == Some(TextExpressionKind::Single)
60	            }
61	            Svelte => p.options().svelte,
62	            Vue => p.options().vue,
63	        }
64	    }
65	}
