162	fn is_possible_component(p: &HtmlParser, tag_name: &str) -> bool {
163	    tag_name
164	        .chars()
165	        .next()
166	        .is_some_and(|c| c.is_ascii_uppercase())
167	        && !p.options().is_html()
168	}
