/// Returns `true` if the parser is positioned at a closing tag (`</...`) for a
/// void element (such as `</br>` or `</input>`).
///
/// Void elements must never have a closing tag, so such a closing tag is bogus.
/// It must not be treated as the closing tag of any enclosing element, so it is
/// parsed as an [`HtmlBogusElement`] child via [`parse_void_closing_tag`].
fn is_at_void_closing_tag(p: &mut HtmlParser) -> bool {
    if !p.at(T![<]) || !p.nth_at(1, T![/]) {
        return false;
    }
    let checkpoint = p.checkpoint();
    p.bump_with_context(T![<], inside_tag_context(p));
    p.bump_with_context(T![/], inside_tag_context(p));
    let is_void = VOID_ELEMENTS
        .iter()
        .any(|tag| tag.eq_ignore_ascii_case(p.cur_text()))
        && !is_possible_component(p, p.cur_text());
    p.rewind(checkpoint);
    is_void
}

